(function(){"use strict";var i={朔望斋:{t:"朔望斋",d:"每月初一\uFF08朔\uFF09与十五\uFF08望\uFF09两日持斋。朔为月之始、望为月之半，佛制于此二日说戒诵经，汉传相沿为斋日。判定：农历每月初一、十五。"},六斋日:{t:"六斋日",d:"每月初八、十四、十五、廿三、廿九、三十日持斋，月小无三十改于廿八。传为四天王太子巡视人间、考察善恶之日，宜持斋修善。判定：每月初八、十四、十五、廿三、廿九、三十，小月改廿八。"},十斋日:{t:"十斋日",d:"每月初一、初八、十四、十五、十八、廿三、廿四、廿八、廿九、三十十日持斋。出《地藏菩萨本愿经》，于此十日诵经、持斋、修善，罪业不增、福慧渐长。判定：每月初一、初八、十四、十五、十八、廿三、廿四、廿八、廿九、三十。"},观音斋:{t:"观音斋",d:"观音菩萨圣诞、成道、出家及诸纪念日前后的持斋日，全年共二十二日。每逢此日持斋称念观世音菩萨名号，尤为相应。判定：全年二十二个固定农历日\uFF08二月初七、二月初九、二月十九等\uFF09，与 lunar.js 内置表一致。"},三长斋月:{t:"三长斋月",d:"正月、五月、九月三个月份全月持斋，又称三长月、三斋月。传为天帝释四天王于正月、五月、九月巡察南赡部洲之月，宜整月茹素持戒、断恶修善。判定：农历正月、五月、九月\uFF08整月\uFF09。"},宿曜:{t:"宿曜",d:`以二十七宿配七曜论日辰吉凶之术，出唐不空译《文殊师利菩萨及诸仙所说吉凶时日善恶宿曜经》。本页二十七宿盘与逐宿吉凶皆依此系。相关：<span class="tip" onclick="showFoliTip('二十七宿')">二十七宿</span>、<span class="tip" onclick="showFoliTip('七曜')">七曜</span>、<span class="tip" onclick="showFoliTip('禽兽')">禽兽</span>、<span class="tip" onclick="showFoliTip('宿曜吉凶歌')">宿曜吉凶歌</span>。`},二十七宿:{t:"二十七宿",d:"宿曜体系取二十七宿轮值，为黄道周天星官之目，较传统二十八宿少牛宿\uFF08宿曜经以牛宿不择吉事而除之\uFF09。逐日一宿轮值，所值之宿主其日吉凶，与农历二十八宿值日两系并行不同表。"},七曜:{t:"七曜",d:"日、月、火、水、木、金、土七星，宿曜体系以此配宿。每宿配一曜，如角宿配木、房宿配日，合称如角木蛟、房日兔，本页宿曜全名即照此合成。"},禽兽:{t:"禽兽",d:"宿曜与星命体系配属每宿的动物形象，如角属蛟、房属兔、斗属獬；与七曜合称即成宿曜全名\uFF08如室火猪\uFF09。本页禽兽取 lunar.js 内置表。"},布萨:{t:"布萨",d:"南传上座部每半月僧团诵戒净心、信众持八戒之制，巴利语 uposatha，日期依南传上座部历法，取朔、上弦、望、下弦四相。与汉传六斋日、十斋日名目不同而所指相近：布萨依南传历法，日期时有出入；本页斋日依汉传农历，不作换算对照。"},佛吉祥日:{t:"佛吉祥日",d:"农历四月十五，南传卫塞节\uFF08Vesak\uFF09日期，一日之中纪念释迦牟尼佛诞辰、成道、涅槃三期同庆\uFF08月圆日\uFF09，南传诸国佛教年历首重之日。与汉传四月初八佛诞分属两系，本页两说并列、各照其历。"},佛欢喜日:{t:"佛欢喜日",d:"农历七月十五，僧众三月安居期满之日，诸佛欢喜；汉传于此日设盂兰盆供，荐拔先亡。与朔望斋、十斋日的七月十五同日，属斋日而兼节庆。"},弥勒菩萨圣诞:{t:"弥勒菩萨圣诞",d:"农历正月初一，弥勒菩萨示现成佛之纪念日，汉传佛教定为弥勒菩萨圣诞。"},定光佛圣诞:{t:"定光佛圣诞",d:"农历正月初六，定光佛诞辰。定光佛又作锭光佛，为燃灯佛之前身。"},释迦牟尼佛出家:{t:"释迦牟尼佛出家",d:"农历二月初八，释迦牟尼佛舍王宫出家求道之纪念日。"},释迦牟尼佛涅槃:{t:"释迦牟尼佛涅槃",d:"农历二月十五，释迦牟尼佛入涅槃之纪念日。"},观世音菩萨圣诞:{t:"观世音菩萨圣诞",d:"农历二月十九，观世音菩萨诞辰，汉传佛教定为观音圣诞。"},普贤菩萨圣诞:{t:"普贤菩萨圣诞",d:"农历二月廿一，普贤菩萨诞辰。"},准提菩萨圣诞:{t:"准提菩萨圣诞",d:"农历三月十六，准提菩萨诞辰。"},文殊菩萨圣诞:{t:"文殊菩萨圣诞",d:"农历四月初四，文殊菩萨诞辰。"},释迦牟尼佛圣诞:{t:"释迦牟尼佛圣诞",d:"农历四月初八，释迦牟尼佛诞辰，汉传佛教浴佛节。"},药王菩萨圣诞:{t:"药王菩萨圣诞",d:"农历四月廿八，药王菩萨诞辰。"},伽蓝菩萨圣诞:{t:"伽蓝菩萨圣诞",d:"农历五月十三，伽蓝菩萨圣诞。汉传丛林以关公为伽蓝菩萨。"},韦驮菩萨圣诞:{t:"韦驮菩萨圣诞",d:"农历六月初三，韦驮菩萨诞辰。"},观音菩萨成道:{t:"观音菩萨成道",d:"农历六月十九，观世音菩萨成道之纪念日。"},大势至菩萨圣诞:{t:"大势至菩萨圣诞",d:"农历七月十三，大势至菩萨诞辰。"},龙树菩萨圣诞:{t:"龙树菩萨圣诞",d:"农历七月廿四，龙树菩萨诞辰。"},地藏菩萨圣诞:{t:"地藏菩萨圣诞",d:"农历七月三十，地藏菩萨诞辰。"},月光菩萨圣诞:{t:"月光菩萨圣诞",d:"农历八月十五，月光菩萨诞辰。"},燃灯佛圣诞:{t:"燃灯佛圣诞",d:"农历八月廿二，燃灯佛诞辰。"},摩利支天菩萨圣诞:{t:"摩利支天菩萨圣诞",d:"农历九月初九，摩利支天菩萨诞辰。"},观世音菩萨出家:{t:"观世音菩萨出家",d:"农历九月十九，观世音菩萨出家之纪念日。"},药师琉璃光佛圣诞:{t:"药师琉璃光佛圣诞",d:"农历九月三十，药师琉璃光如来诞辰。"},达摩祖师圣诞:{t:"达摩祖师圣诞",d:"农历十月初五，达摩祖师诞辰。"},文殊菩萨出家:{t:"文殊菩萨出家",d:"农历十月二十，文殊菩萨出家之纪念日。"},阿弥陀佛圣诞:{t:"阿弥陀佛圣诞",d:"农历十一月十七，阿弥陀佛诞辰。"},日光菩萨圣诞:{t:"日光菩萨圣诞",d:"农历十一月十九，日光菩萨诞辰。"},释迦牟尼佛成道:{t:"释迦牟尼佛成道",d:"农历十二月初八，释迦牟尼佛成道之纪念日，汉传佛教腊八节。"},监斋菩萨圣诞:{t:"监斋菩萨圣诞",d:"农历十二月廿三，监斋菩萨诞辰。"},华严菩萨圣诞:{t:"华严菩萨圣诞",d:"农历十二月廿九，华严菩萨诞辰。"},斋期:{t:"斋期",d:"持斋之日。斋者不过中食、茹素持戒，于斋日宜诵经、礼忏、行善，不杀生、不荤腥。本页斋期共五类：朔望斋、六斋日、十斋日、观音斋为逐日之斋，三长斋月为整月之斋，判定口径见各条。"},宿曜吉凶歌:{t:"宿曜吉凶歌",d:"逐宿所系吉凶歌诀，述该宿值日宜行与不宜行之事\uFF08如角宿造作主荣昌、亢宿造作枉灾殃\uFF09。歌诀沿《宿曜经》一系通行本录注，与本页逐宿释义同看。"}},n={角:{d:"木曜配蛟，属东方青龙。吉宿。禀性和善，造作营修主荣昌，外进田财，嫁娶婚姻出贵子；惟埋葬不可用，凶事相妨。"},亢:{d:"金曜配龙，属东方青龙。凶宿。禀性刚直，造作施恩反成枉灾；嫁娶婚姻亦非所宜，葬埋尤不可用，主守旧安分为吉。"},氐:{d:"土曜配貉，属东方青龙。凶宿。禀性沉静，造作主凶，出行买卖不利；埋葬婚姻皆宜避，安分守常自可无虞。"},房:{d:"日曜配兔，属东方青龙。吉宿。禀性清明，造作主吉，田园广进、财帛丰盈，嫁娶安葬俱宜，为诸事通用之日。"},心:{d:"月曜配狐，属东方青龙。凶宿。禀性多虑，造作凶不可行，男女易生是非；婚姻葬埋皆所忌，宜静守不宣动。"},尾:{d:"火曜配虎，属东方青龙。吉宿。禀性豪爽，造作主富，埋葬平顺、娶婚姻者贵；用事多得人和，进益自然来。"},箕:{d:"水曜配豹，属东方青龙。吉宿。禀性机变，造作主兴家，开门放水、埋葬修造俱吉，门户昌盛人丁旺。"},斗:{d:"木曜配獬，属北方玄武。吉宿。禀性稳重，造作主招财，修坟安葬、开门放水皆吉，婚姻偕老福绵绵。"},女:{d:"土曜配蝠，属北方玄武。凶宿。禀性柔顺，造作不利于宅；嫁娶开门皆非所宜，宜安静守分，大事勿举。"},虚:{d:"日曜配鼠，属北方玄武。凶宿。禀性虚灵，造作主灾殃，儿童见损伤；婚娶亦非吉日，凡事虚而不实，宜守不宜进。"},危:{d:"月曜配燕，属北方玄武。凶宿。禀性谨慎，造作不利、埋葬有妨；守旧安分为上，勿行大事、勿犯险远。"},室:{d:"火曜配猪，属北方玄武。吉宿。禀性敦厚，造作主兴隆，富贵双全、婚姻祭葬俱吉，为营宅修造之首吉。"},壁:{d:"水曜配獝，属北方玄武。吉宿。禀性坚毅，造作主进财，埋葬婚姻皆相宜，增福添寿、门庭焕然。"},奎:{d:"木曜配狼，属西方白虎。凶宿。造作得祯祥，家内荣和；惟埋葬、开门放水皆凶，官事刑伤，宜避。"},娄:{d:"金曜配狗，属西方白虎。吉宿。禀性平和，造作主顺遂，婚姻祭葬开门放水俱宜，进人丁、兴家业。"},胃:{d:"土曜配彘，属西方白虎。吉宿。禀性充实，造作大吉，嫁娶贺祭、埋葬皆宜，子孙贤贵、财禄有余。"},昴:{d:"日曜配鸡，属西方白虎。凶宿。造作进田牛，惟埋葬、开门放水、婚姻皆凶，死别生离，宜避。"},毕:{d:"月曜配乌，属西方白虎。吉宿。禀性温厚，造作主兴旺，婚姻祭葬、开门放水俱吉，田园广进福寿长。"},觜:{d:"火曜配猴，属西方白虎。凶宿。造作有徒刑，三年伶丁；埋葬卒死，家门退败，大事勿用。"},参:{d:"水曜配猿，属西方白虎。吉宿。造作旺人家，开门放水加官职，子孙见田加；惟埋葬招疾，婚姻遭刑克。"},井:{d:"木曜配犴，属南方朱雀。吉宿。造作旺蚕田，金榜题名，开门放水招财；惟埋葬须防惊卒死，狂颠风疾。"},鬼:{d:"金曜配羊，属南方朱雀。凶宿。造作卒人亡，开门放水伤死；惟埋葬官禄至，嫁娶不久长。"},柳:{d:"土曜配獐，属南方朱雀。凶宿。禀性缠绵，造作多官非，盗贼相缠不可当；婚姻亦非吉，守静为宜。"},星:{d:"日曜配马，属南方朱雀。凶宿。造作好新房、进职加官；惟埋葬、放水皆凶，婚姻不利，凡事宜缓。"},张:{d:"月曜配鹿，属南方朱雀。吉宿。禀性开张，造作主财旺，开门放水、婚姻葬埋俱吉，五谷丰盈福满堂。"},翼:{d:"火曜配蛇，属南方朱雀。凶宿。禀性飞扬，造作主灾殃，少年见伤亡；婚姻埋葬皆所忌，宜守静自安。"},轸:{d:"水曜配蚓，属南方朱雀。吉宿。禀性深远，造作主荣华，婚姻埋葬、开门放水俱宜，代代儿孙有名声。"}};function o(t){var d=i[t];return d?{t:d.t,d:d.d}:null}function s(t,d){var a=n[t];return a?{t:d||t,d:a.d}:null}typeof window<"u"&&(window.FOLI_DICT=i,window.FOLI_XIU27_NOTE=n,window.foliMean=o,window.foliXiuMean=s),typeof module<"u"&&module.exports&&(module.exports={FOLI_DICT:i,FOLI_XIU27_NOTE:n,foliMean:o,foliXiuMean:s})})();
